    coord_map = None
    if coords is not None:
        if isinstance(coords, dict):
            coord_map = coords
        else:
            coord_map = {}
            for idx, p in enumerate(coords):
                try:
                    coord_map[idx] = (p[0], p[1])
                except:
                    pass

    def coord_of(i):
        if coord_map is None:
            return None
        if i in coord_map:
            return coord_map[i]
        try:
            ii = int(i)
            if ii in coord_map:
                return coord_map[ii]
        except:
            pass
        return None

    def d(i, j):
        if dist is not None:
            try:
                return dist[i][j]
            except:
                try:
                    return dist[int(i)][int(j)]
                except:
                    pass
        if coord_map is not None:
            a = coord_of(i)
            b = coord_of(j)
            if a is not None and b is not None:
                dx = a[0] - b[0]
                dy = a[1] - b[1]
                return (dx * dx + dy * dy) ** 0.5
        return 0.0 if i == j else 1.0

    if not customers:
        return []

    routes = [[c] for c in customers]
    loads = [demand_of(c) for c in customers]
    active = [True] * len(routes)
    route_of = {}
    for idx, c in enumerate(customers):
        route_of[c] = idx

    savings = []
    n = len(customers)
    for a in range(n):
        i = customers[a]
        for b in range(a + 1, n):
            j = customers[b]
            s = d(depot_id, i) + d(depot_id, j) - d(i, j)
            savings.append((s, i, j))
    savings.sort(key=lambda x: (-x[0], x[1], x[2]))

    def find_route_of(node):
        idx = route_of.get(node, None)
        if idx is None or idx < 0 or idx >= len(routes) or not active[idx]:
            return None
        return idx

    for _, i, j in savings:
        ri = find_route_of(i)
        rj = find_route_of(j)
        if ri is None or rj is None or ri == rj:
            continue
        if loads[ri] + loads[rj] > capacity:
            continue

        r1 = routes[ri]
        r2 = routes[rj]
        merged = None
        if r1[-1] == i and r2[0] == j:
            merged = r1 + r2
        elif r1[0] == i and r2[-1] == j:
            merged = list(reversed(r1)) + list(reversed(r2))
        elif r1[-1] == i and r2[-1] == j:
            merged = r1 + list(reversed(r2))
        elif r1[0] == i and r2[0] == j:
            merged = list(reversed(r1)) + r2

        if merged is not None:
            routes[ri] = merged
            loads[ri] += loads[rj]
            for node in routes[rj]:
                route_of[node] = ri
            routes[rj] = []
            loads[rj] = 0
            active[rj] = False

    final_routes = [routes[i] for i in range(len(routes)) if active[i] and routes[i]]

    repaired = []
    for r in final_routes:
        cur = []
        cur_load = 0
        for node in r:
            q = demand_of(node)
            if cur and cur_load + q > capacity:
                repaired.append(cur)
                cur = [node]
                cur_load = q
            else:
                cur.append(node)
                cur_load += q
        if cur:
            repaired.append(cur)
    final_routes = repaired

    def route_cost(seq):
        if not seq:
            return 0.0
        total = d(depot_id, seq[0])
        for k in range(len(seq) - 1):
            total += d(seq[k], seq[k + 1])
        total += d(seq[-1], depot_id)
        return total

    improved = []
    for r in final_routes:
        best = r[:]
        best_cost = route_cost(best)
        changed = True
        while changed:
            changed = False
            L = len(best)
            for a in range(L):
                for b in range(a + 1, L):
                    cand = best[:a] + best[a:b + 1][::-1] + best[b + 1:]
                    c = route_cost(cand)
                    if c + 1e-12 < best_cost or (abs(c - best_cost) <= 1e-12 and cand < best):
                        best = cand
                        best_cost = c
                        changed = True
        improved.append(best)

    improved.sort(key=lambda r: (r[0], r))
    return improved
